package com.medflow.nutrition;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.LocalDate;import java.util.*;
import org.springframework.security.core.Authentication;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/nutrition") public class NutritionController {
 private final Access access;public NutritionController(Access access){this.access=access;}
 public record Profile(@NotBlank @Pattern(regexp="VARIETY|CONSISTENCY")String goal,@Size(max=500)String notes){}
 public record Progress(@NotNull @PastOrPresent LocalDate entryDate,@Min(0) @Max(20)int fruitServings,@Size(max=500)String notes){}
 @GetMapping("/foods") public Map<String,Object> foods(@RequestParam(defaultValue="") @Size(max=100)String search){return Map.of("basis","Per 100 grams edible portion; USDA SR Legacy records. Two-fruit demonstration dataset, not a balanced diet.","foods",access.rows("SELECT * FROM foods WHERE LOWER(name) LIKE ? ORDER BY name LIMIT 100","%"+search.toLowerCase(Locale.ROOT)+"%"));}
 @GetMapping("/profile") public Map<String,Object> profile(Authentication a){access.roles(a,"PATIENT");return access.one("SELECT * FROM nutrition_profiles WHERE owner_user_id=?",access.subject(a));}
 @PutMapping("/profile") @Transactional public Map<String,Object> profile(@Valid @RequestBody Profile r,Authentication a){access.roles(a,"PATIENT");UUID id=access.subject(a);if(access.db.update("UPDATE nutrition_profiles SET goal=?,notes=?,updated_at=CURRENT_TIMESTAMP WHERE owner_user_id=?",r.goal(),r.notes(),id)==0)access.db.update("INSERT INTO nutrition_profiles(owner_user_id,goal,notes) VALUES(?,?,?)",id,r.goal(),r.notes());return profile(a);}
 @GetMapping("/recommendations") public Map<String,Object> recommendations(Authentication a){access.roles(a,"PATIENT");var profile=profile(a);return Map.of("method","Transparent rule: VARIETY lists the two available foods alphabetically; CONSISTENCY lists them by source ID. No disease or nutritional-need inference.","goal",profile.get("goal"),"foods",access.rows(profile.get("goal").equals("VARIETY")?"SELECT * FROM foods ORDER BY name":"SELECT * FROM foods ORDER BY id"),"limitation","General food information only. Not a meal plan, clinical recovery plan, or individualized diet. Consult a qualified clinician for clinical nutrition.");}
 @GetMapping("/progress") public List<Map<String,Object>> progress(Authentication a){access.roles(a,"PATIENT");return access.rows("SELECT * FROM wellness_progress WHERE owner_user_id=? ORDER BY entry_date DESC LIMIT 100",access.subject(a));}
 @PostMapping("/progress") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public Map<String,Object> progress(@Valid @RequestBody Progress r,Authentication a){access.roles(a,"PATIENT");UUID id=UUID.randomUUID();access.db.update("INSERT INTO wellness_progress(id,owner_user_id,entry_date,fruit_servings,notes) VALUES(?,?,?,?,?)",id,access.subject(a),r.entryDate(),r.fruitServings(),r.notes());return access.one("SELECT * FROM wellness_progress WHERE id=?",id);}
}
